// mkcontent4.js - build content_v4.js from content_v3.js
// v4: national arm (EPA AQS, 123 sites) added with Colorado as the case study;
//     effective mixing heights corrected to local conditions; Sect. 5.4 rewritten
//     around the finding that the lag which matters is site dependent.
const fs = require("fs");
const C = require("./content_v3.js");

const S = C.sections;
const find = (pred) => { const i = S.findIndex(pred); if (i < 0) throw new Error("not found: " + pred); return i; };
const byHead = (t) => find(s => (s.h1 || s.h2 || "") === t);
const setP = (t, ps) => { S[byHead(t)].p = ps; };
const rename = (t, nt) => { const s = S[byHead(t)]; if (s.h2) s.h2 = nt; else s.h1 = nt; };

// ---------------------------------------------------------------- title, abstract
C.title = "TEMPO formaldehyde columns and routine surface air toxics monitoring in " +
  "the United States: day-to-day agreement at 123 sites, the timing of satellite–sample " +
  "matching, and a Colorado case study";

C.abstract = [
"Formaldehyde (HCHO) is a carcinogenic hazardous air pollutant and a leading contributor to estimated cancer risk from outdoor air toxics in the United States. The geostationary Tropospheric Emissions: Monitoring of Pollution (TEMPO) instrument retrieves HCHO columns hourly over North America, but evaluations of these retrievals have relied on column measurements, and comparisons of satellite HCHO with routine surface monitoring have been limited to seasonal means from polar-orbiting instruments. We compare TEMPO Level 3 version 4 HCHO columns with every integrated carbonyl sample reported to the United States Air Quality System (AQS) in 2024–2025 — 16 383 samples at 123 sites in 37 states, of which 102 sites sample for 24 h, 40 for 8 h and 4 for 3 h — and examine Colorado's air toxics network in detail as a case study, using the state's own data packets and a classification of every sample period by wildfire smoke.",
"Nationally, 70 % of 24 h samples had at least one TEMPO scan passing quality screening. The pooled correlation between the daily mean column and 24 h surface HCHO was 0.42 (n = 6106) and 0.40 after removing site and calendar-month means, which isolates day-to-day covariation. Agreement was significant at 122 of 141 site–duration combinations; the median day-to-day correlation at individual 24 h sites was 0.48 (interquartile range 0.27–0.59) and spanned −0.24 to 0.89. In Colorado, where the case study draws on the state packets, the pooled correlation across seven sites was 0.56 and the day-to-day correlation 0.30 — below the national median — and the two independent data pathways, state packets and AQS, gave site correlations agreeing to within 0.02 at the three sites with two-year records.",
"Agreement improved consistently with spatial averaging, from single 0.02° cells to 5 × 5 cell blocks, both nationally and in Colorado. In Colorado we show that this is almost entirely the averaging down of retrieval noise: successive scans imply that noise accounts for about half of the day-to-day variance of a 3 × 3 daily column, capping the attainable correlation near 0.7. The column's seasonal amplitude exceeded the surface amplitude (3.0-fold against 1.7-fold from winter to summer in Colorado), and the effective mixing height implied by the column-to-surface ratio was 0.83 km in Colorado, about half the modelled boundary layer depth, against 1.09 km nationally, close to it.",
"The hour at which a sample is collected mattered more than its length. At the two California sites that sample five 3 h windows a day, day-to-day agreement was as strong in the 05:00–08:00 window (r = 0.44) as at midday (0.41) and absent in the late afternoon (0.17); at Colorado's two 3 h sites, which sample only 06:00–09:00 MST, agreement was absent during the sampling window (0.11) and strongest three hours after it (0.40). Across the 40 sites sampling 8 h blocks, the midday block outperformed the morning block (0.42 against 0.34). The lag that matters is therefore site dependent rather than universal, consistent with the sampled air entering the observed column only once the morning boundary layer has deepened, at an hour that varies with local morning stability. Wildfire smoke, classified in Colorado from NOAA Hazard Mapping System analyses, raised both surface and column HCHO within season, did not reduce TEMPO coverage, and contributed to day-to-day agreement. TEMPO captures the seasonal cycle and regional episodes seen by surface air toxics monitors across the country; its day-to-day skill at an individual monitor is moderate, strongly site dependent, and governed by retrieval noise and by when the satellite looks relative to when the air was sampled."
];

C.shortSummary =
"Satellites now measure formaldehyde, a cancer-causing air pollutant, every daylight hour over North America. We compared these measurements with every routine surface sample collected across the United States in 2024-2025, at 123 sites, and looked at Colorado's network in detail. The satellite tracked day-to-day changes at most sites, but how well depended on where the monitor was and on what time of day the sample was collected: morning samples match the satellite only once the morning air has mixed upward, which happens at a different hour in different places.";

C.notes = [
"Numbers come from the pipeline runs of 11-14 September 2026, analysis code at commit 14a1257 (github.com/pdez90/coatts_hcho). Later commits change manuscript text only and no number. Re-check every number if the pipeline is rerun.",
"Changes from v3: the national arm is complete and now frames the paper (new Sects. 2.3, 3.7, 4.9, 4.10 and 5.6, Table 5 and Figs. 9-11), with Colorado as the case study; the title, abstract, introduction and conclusions were rewritten accordingly. Effective mixing heights are now computed at local temperature and pressure, having confirmed via AQS that CDPHE reports concentrations at standard conditions - every H_{eff} value in Sects. 3.2, 4.5 and 5.3 and in Tables 3 and 4 is about 15 % larger than in v3. Section 5.4 is rewritten around the finding that the lag which matters is site dependent: California's morning samples track TEMPO during the sampling window, Colorado's do not. Figures renumbered only by addition (Figs. 1-8 unchanged).",
"Still to settle with CDPHE: what COOPs stands for; the two samples stamped 23:59 on 12 June 2025 (excluded here; AQS shows no such stamps); and how to cite CDPHE's answers (personal communication?). The reporting-conditions question is now settled from AQS and needs no further reply.",
"Author list, affiliations, author contributions, acknowledgements and funding are placeholders. Consider inviting CDPHE ATOPs staff as co-authors.",
"Add Figure 1: site map of the Colorado sites (seven COATTS sites and the two COOPs sites over terrain and county outlines). Fig. 9 shows the national sites. Current Figs. 1-11 will renumber to 2-12.",
"Before submission: move the text into the Copernicus Word template; archive the code on Zenodo and cite its DOI; decide whether to deposit the matched datasets; complete the Zoogman et al. (2017) author list; confirm the TEMPO dataset citation on the DOI landing page; and re-check the claim of novelty in the Introduction against the literature.",
"Yellow-highlighted text marks statements to verify or decisions to make."
];

// ---------------------------------------------------------------- 1 Introduction
{
  const s = S[byHead("1 Introduction")];
  // replace the final two framing paragraphs
  s.p[3] = "An hourly geostationary instrument changes this arithmetic, because every sample day yields a dozen observations and the satellite can be matched to the hours a sample actually covers. To our knowledge TEMPO HCHO has not yet been evaluated against routine surface air toxics measurements at daily or sub-daily resolution [[re-check before submission]]. Such networks collect integrated samples designed for long-term risk assessment rather than satellite validation, so the practical questions are how often a usable satellite observation is available, how well TEMPO tracks the seasonal cycle and day-to-day variations at individual monitors, how the comparison depends on the choice of spatial and temporal matching, how much the answer varies from monitor to monitor, and what limits the agreement that remains.";
  s.p[4] = "Here we compare TEMPO Level 3 version 4 HCHO columns with surface HCHO measured in 2024–2025 at every United States monitor reporting formaldehyde to EPA's Air Quality System: 123 sites in 37 states, including National Air Toxics Trends Stations, NCore multipollutant sites and Photochemical Assessment Monitoring Stations, with sample durations of 24, 8 and 3 h. Within that network we treat Colorado as a case study. Colorado designated formaldehyde a priority toxic air contaminant, its network spans an urban–industrial corridor north of Denver, oil-and-gas-producing and agricultural areas on the northern Front Range, southern Front Range cities and a valley city on the Western Slope, and its data reach us both through the state's own data packets, which carry information AQS does not hold, and through AQS, which allows the two pathways to be cross-checked. The terrain is also demanding: elevation and boundary layer structure complicate the relationship between column and surface.";
  s.p[5] = "We (i) quantify the availability of screened TEMPO observations on sample days; (ii) separate seasonal from day-to-day agreement, nationally and site by site; (iii) test the sensitivity of the comparison to cloud screening, spatial averaging and time-of-day selection; (iv) use the sub-daily samples, whose sampling windows are recorded in AQS, to examine how agreement depends on the delay between sampling and the satellite view, and on the hour at which sampling takes place; (v) assess the influence of wildfire smoke identified by the NOAA Hazard Mapping System (HMS) in the Colorado case study; and (vi) test candidate explanations for the agreement we find, including retrieval noise, terrain and time of day.";
}

// ---------------------------------------------------------------- 2 Data: new 2.3
rename("2.3 TEMPO formaldehyde columns", "2.4 TEMPO formaldehyde columns");
rename("2.4 NOAA Hazard Mapping System smoke analyses", "2.5 NOAA Hazard Mapping System smoke analyses");
rename("2.1 Colorado Air Toxics Trends network (24 h samples)",
       "2.1 Colorado Air Toxics Trends network (24 h samples; case study)");
rename("2.2 COOPs ozone-precursor sites (3 h samples)",
       "2.2 COOPs ozone-precursor sites (3 h samples; case study)");

const natData = {
  h2: "2.3 National formaldehyde monitors (EPA Air Quality System)",
  p: [
"Formaldehyde is measured routinely across the United States by state, local and tribal agencies and reported to EPA's Air Quality System (AQS) as parameter 43502 (U.S. EPA, 2025). Almost all of these measurements use the same approach as Colorado's: air is drawn through a 2,4-dinitrophenylhydrazine-coated cartridge and the derivative is quantified by high-performance liquid chromatography, following Compendium Method TO-11A (U.S. EPA, 1999). Of the samples analysed here, 76 % were collected with a potassium-iodide ozone scrubber upstream of the cartridge, 16 % on a bare silica cartridge and 8 % behind a heated ozone denuder. Three programmes account for most of the monitors: the National Air Toxics Trends Stations (NATTS), which measure long-term trends in priority air toxics at a small number of urban and rural sites; the NCore multipollutant network; and the Photochemical Assessment Monitoring Stations (PAMS) in ozone non-attainment areas, where carbonyl sampling is sub-daily and often seasonal.",
"We retrieved every formaldehyde sample reported to AQS for 1 January 2024 to 31 December 2025: 16 383 samples at 123 sites in 37 states (Table 5). For each sample AQS records the local standard time at which sampling began, the corresponding GMT date and time, and the sample duration, so the sampling window of every sample is known without a time zone assumption. This is precisely the information the Colorado data packets lack (Sect. 2.2), and it is what makes a national analysis of sampling time possible. Records carrying an AQS null data qualifier were removed (5009 samples carry at least one qualifier of any kind), and where more than one method within a site reported the same window their values were averaged. AQS reports these measurements in parts per billion carbon, which for formaldehyde equals parts per billion by volume; we converted to mass concentration at 25 °C and 1 atm, matching the reporting convention used for the Colorado packets (Sect. 3.2).",
"The network divides into three sampling regimes. One hundred and two sites collect 24 h samples (8730 samples, 30 states), almost all beginning at midnight local standard time, typically every third or sixth day; 23 of these are NATTS sites and 21 are PAMS sites. Forty sites collect 8 h samples (6972 samples, 29 states), every one of them in the same three fixed blocks beginning at 04:00, 12:00 and 20:00 local standard time, so that a single site samples the morning transition, the well-mixed afternoon and the night separately. Four sites collect 3 h samples (681 samples): the two Colorado COOPs sites of Sect. 2.2, which sample only 06:00–09:00 MST, and two sites in California's San Joaquin Valley, Bakersfield-Muni and Clovis-Villa, which sample five windows a day beginning at 05:00, 08:00, 12:00, 16:00 and 23:00 LST between June 2024 and August 2025. The Colorado 24 h sites appear in both arms of this study, once through the state packets and once through AQS, which we use as a check on the two data pathways (Sect. 4.9)."
  ]
};
S.splice(byHead("2.4 TEMPO formaldehyde columns"), 0, natData);

// ---------------------------------------------------------------- 3.2 corrected
setP("3.2 Effective mixing height", [
"To relate the column to the surface concentration we converted the surface mass concentration to a number density n_{s} (molecules cm^{-3}) and defined an effective mixing height H_{eff} = Ω/n_{s}, where Ω is the TEMPO column. H_{eff} is the depth of a uniform layer at the surface concentration that would contain the observed column. It combines the vertical distribution of HCHO (including the free-tropospheric column), biases in the retrieval and in the surface measurement, and the mismatch between the sampling period and daytime satellite sampling, so it is used here as a diagnostic rather than a physical boundary layer depth.",
"The conversion depends on the conditions at which concentrations are reported. Cross-checking the CDPHE packets against the same samples in AQS shows that the two differ by exactly the factor M/24.45, where M = 30.026 g mol^{-1} is the molar mass of HCHO: the packets report mass concentrations at standard conditions (25 °C, 1 atm), and AQS reports the corresponding mixing ratio. We therefore converted the reported concentration to a mixing ratio, χ = C × 24.45/M, and then to a number density at the conditions of the air, n_{s} = χ × 10^{-9} p/(k_{B}T), using the TEMPO surface pressure at the site (median 840 hPa at the Colorado sites) and, for the Colorado arm, the site- and month-mean surface temperature (median 8.8 °C). Ignoring this correction, as an analysis that assumed local-condition reporting would, overestimates n_{s} and understates H_{eff} by about 15 % at the elevations of the Front Range sites. For the national arm, where no surface temperature accompanies the AQS records, a fixed 15 °C was used with the retrieved surface pressure; a 10 K error in this assumption changes H_{eff} by 3 %. H_{eff} was computed only for positive columns and compared with the TEMPO PBL height averaged over the same valid scans."
]);

// ---------------------------------------------------------------- 3.7 national methods
const natMethods = {
  h2: "3.7 The national comparison",
  p: [
"The national arm repeats the Colorado analysis at every AQS site, with three differences forced by its scale. First, extraction: requesting a separate OPeNDAP subset for each of 123 sites would multiply the number of requests by the number of sites, so sites were grouped into 50 clusters of at most 1.25° latitude by 2.5° longitude, one subset was requested per cluster and scan, and the 5 × 5 cell block around each site was cut from it afterwards. Only scans that a cluster's samples actually require were retrieved: the days a site sampled, and for sub-daily samples the sampling window padded by 3 h on each side so that the lagged windows are covered. This produced 88 622 cluster-scans and 3.97 million cell records.",
"Second, matching. A sampling window is expressed as the set of hours it spans, in UTC, and a scan is assigned to a window when the hour containing its midpoint belongs to that set. Because every AQS sampling window begins on the hour, this is exact. Lagged windows are the same set shifted by −3, 0, +3 or +6 h; lags are applied only to sub-daily samples, since a 24 h window shifted by a few hours is almost the same window. Screening, block sizes and cloud thresholds are as in Sect. 3.1, and the primary configuration is again an effective cloud fraction of 0.2 and a 3 × 3 block.",
"Third, statistics. Correlations and within-month anomaly correlations are computed as in Sect. 3.3, pooled by sample duration and lag, by the local standard hour at which the sampling window begins, and site by site (sites with at least 10 matched samples, and window start hours with at least 12). Because the number of sites is large, the pooled regression uses ordinary least squares with the column as a fixed effect and fixed effects for site and calendar month, rather than a mixed model. Wildfire smoke is not classified in the national arm; the HMS analysis remains part of the Colorado case study."
  ]
};
S.splice(byHead("4 Results"), 0, natMethods);

// ---------------------------------------------------------------- 4.5 corrected numbers
setP("4.5 Column–surface relationship", [
"The seasonal amplitude of the column exceeded that of the surface concentration. From winter to summer, median surface HCHO on matched days increased from 2.12 to 3.51 µg m^{-3} (1.7-fold), whereas the median column increased from 2.18 to 6.63 × 10^{15} molecules cm^{-2} (3.0-fold). Correspondingly, the median effective mixing height H_{eff} increased from 0.62 km in winter and 0.65 km in spring to 1.06 km in summer, and was 0.83 km in autumn (Fig. 5). Across all matched days, median H_{eff} was 0.83 km, compared with a median TEMPO PBL height of 1.55 km. H_{eff} was well below the PBL height in spring (0.65 versus 1.77 km), summer (1.06 versus 2.11 km) and autumn (0.83 versus 1.28 km) and close to it in winter (0.62 versus 0.64 km). By site, median H_{eff} ranged from 0.72 km at Grand Junction and 0.76 km at Commerce City to 1.06 km at Colorado Springs and 1.13 km at Cañon City."
]);

// Fig. 5 caption unchanged in wording but note the conditions
{
  const i = find(s => s.fig && s.fig.file === "fig3_effective_height_by_month.png");
  S[i].fig.caption = "Figure 5. Monthly distributions of the effective mixing height H_{eff} (TEMPO column divided by the surface number density at the temperature and pressure of the air, Sect. 3.2) on matched days by site. Orange diamonds show the median TEMPO PBL height on the same days. The vertical axis is truncated at the 98th percentile.";
}

// ---------------------------------------------------------------- Table 3 and 4: H_eff row
{
  const t3 = S[find(s => s.table && /^Table 3\./.test(s.table.caption))].table;
  const r = t3.rows.find(r => r[0].startsWith("Median H_{eff}"));
  r[1] = "0.95 / 0.54"; r[2] = "0.95 / 1.56"; r[3] = "0.90 / 2.25";

  const t4 = S[find(s => s.table && /^Table 4\./.test(s.table.caption))].table;
  const heff = { "DJF|none": "0.62", "MAM|none": "0.65", "MAM|light": "0.72",
    "JJA|none": "1.06", "JJA|light": "1.12", "JJA|medium–heavy": "0.96",
    "SON|none": "0.80", "SON|light": "0.98", "SON|medium–heavy": "1.02" };
  t4.rows.forEach(r => { const k = r[0] + "|" + r[1]; if (heff[k]) r[6] = heff[k]; });
  t4.caption = t4.caption.replace("effective mixing height by season",
    "effective mixing height (at the temperature and pressure of the air, Sect. 3.2) by season");
}

// ---------------------------------------------------------------- 4.9 / 4.10 national results
const natResults = [
{
  h2: "4.9 Agreement across the national network",
  p: [
"TEMPO coverage of the 24 h samples was slightly lower nationally than in Colorado: 70 % of the 8730 samples had at least one scan passing the primary screening, against 75 % in Colorado, with a median of 11 usable scans per sample day. Coverage varied widely between sites, from around 90 % in Arizona, southern California and on the Texas Gulf coast to below 50 % in western Oregon, Vermont and upstate New York, with the lowest values at Tualatin, Oregon (37 %) and Proctor Maple Research Center, Vermont (40 %).",
"Pooled across the 24 h sites, the daily mean column and the 24 h surface concentration correlated at r = 0.42 (ρ = 0.48, n = 6106), and after removing site and calendar-month means the day-to-day correlation was 0.40 (n = 5218 in 1262 site-months). Two comparisons make these numbers interpretable. First, the pooled correlation is well below the median correlation computed within individual sites (0.64; Fig. 9), so pooling across the country dilutes rather than inflates: TEMPO tracks variation at a given monitor considerably better than it tracks the differences between monitors, whose column-to-surface ratios differ with climate, mixing depth and the free-tropospheric background. Second, pooling adds almost nothing over the day-to-day correlation nationally (0.42 against 0.40), whereas in Colorado it adds a great deal (0.56 against 0.30). Colorado's seven sites share one regional seasonal cycle, which the pooled statistic rewards; across the country the seasonal cycles and mean levels are heterogeneous enough to cancel that gain. The day-to-day correlation is therefore the quantity to compare between networks, and by that measure Colorado is below the national norm. The regression of surface concentration on the column, with fixed effects for site and calendar month, gave 0.163 ± 0.006 µg m^{-3} per 10^{15} molecules cm^{-2} (p < 10^{-100}), close to the 3 h Colorado estimate of 0.136 ± 0.037 in the window three hours after sampling. Median H_{eff} across the 24 h sites was 1.09 km against a median TEMPO PBL height of 1.04 km, so nationally the column and the modelled mixed layer are consistent with a well-mixed HCHO profile; Colorado's H_{eff} of about half the PBL height is not the general case.",
"Agreement is significant at most individual sites but far from uniform (Fig. 9). Of 141 site–duration combinations with at least 10 matched samples, 122 had a significant positive correlation. At the 97 sites with enough 24 h samples the median correlation was 0.64 (interquartile range 0.45–0.72) and the median day-to-day correlation 0.48 (0.27–0.59), ranging from 0.89 at Medford, Oregon, 0.85 at Fresno and 0.79 at Stockton, California, to values indistinguishable from zero at a dozen sites and −0.24 at St. Charles Mesa, Colorado. The 40 sites sampling 8 h blocks behaved similarly (median correlation 0.48, median day-to-day correlation 0.47). Colorado's six 24 h AQS sites had a median day-to-day correlation of 0.35, below the national median of 0.48 and below the medians for Iowa (0.59), Michigan (0.59), Pennsylvania (0.54) and California (0.40), and above New York (0.33).",
"The two data pathways agree. At the three Colorado sites with two-year records, the day-to-day correlation computed from the state's data packets and from the same samples retrieved through AQS differ by at most 0.02 (La Salle 0.62 and 0.61, Commerce City 0.48 and 0.48, Grand Junction 0.21 and 0.22), which is reassuring for both the packet parsing and the AQS unit conversion, and means the case study and the national analysis can be read together.",
"Two features of the national distribution bear on what limits agreement. Sensitivity to the processing choices is the same as in Colorado: pooled over 24 h sites, the correlation rises from 0.39 for single cells to 0.42 for 3 × 3 blocks and 0.43 for 5 × 5 blocks, and a stricter cloud threshold of 0.1 helps slightly (0.44 at 3 × 3) at the cost of 9 % of the samples — the signature of averaging down noise rather than of a change in what is being measured. And agreement is weakest where concentrations are lowest: grouping the 24 h sites into thirds by median surface concentration, the median day-to-day correlation is 0.34 in the lowest third (0.6–2.0 µg m^{-3}), 0.58 in the middle third and 0.46 in the highest. A fixed retrieval noise is a larger fraction of the variance where the signal is small, which is what the Colorado noise analysis (Sect. 4.8) implies should happen."
  ]
},
{ fig: { file: "fig13_national_site_map.png", w: 1650, h: 2640,
  caption: "Figure 9. Day-to-day agreement (within-month anomaly correlation) between TEMPO HCHO columns and surface HCHO at each site, by sample duration, for scans inside the sampling window. Colour shows the correlation and symbol size the number of matched samples. Sites with fewer than 10 matched samples are not shown." } },
{
  h2: "4.10 Sampling window and time of day across the network",
  p: [
"The national sub-daily sites allow the Colorado lag result to be tested where sampling windows differ. Two cautions are needed first. Pooling a lag curve across sites that sample different windows mixes together shifts that mean quite different things — a −3 h shift is the middle of the night for a 05:00 sample and mid-morning for a 12:00 sample — so the pooled curves (Fig. 10) are reported for completeness but are not comparable with Colorado's, where every sample covers the same window. The informative cut is by the hour at which sampling begins (Fig. 11). Second, an 8 h window shifted by 3 h still overlaps the original window by five hours, so lag curves for the 8 h sites are expected to be flat, and they are: the day-to-day correlation is 0.31, 0.38, 0.35 and 0.32 at lags of −3, 0, +3 and +6 h.",
"Grouped by the hour at which the window starts, the pattern is clear and it is not the one Colorado alone would suggest. At the two California sites sampling 3 h blocks, the window beginning at 05:00 LST tracks the surface as well as any: the day-to-day correlation is 0.44 (n = 99) for scans inside the sampling window, essentially the same as the 0.41 of the midday window beginning at 12:00 (n = 100), while the late-afternoon window beginning at 16:00 shows no significant agreement (0.17, n = 91, p = 0.11). The Colorado window beginning at 06:00 MST is the outlier: 0.11 (n = 79, p = 0.35), against 0.40 for the same samples matched to scans three hours later (Sect. 4.6). The 8 h sites show the same ordering more coarsely: the block beginning at 12:00 LST gives a day-to-day correlation of 0.42 (n = 1754) and the block beginning at 04:00, which straddles the morning transition, 0.34 (n = 1698); the block beginning at 20:00 is dark and yields no usable scans.",
"In other words, morning sampling is not intrinsically hard to match to a satellite column. At the California sites, samples collected between 05:00 and 08:00 local time agree with the column measured during those same hours. It is at Colorado's two Front Range sites, sampling one hour later in the day, that the sampling window fails and the window three hours later succeeds."
  ]
},
{ fig: { file: "fig11_national_lag_curve.png", w: 2400, h: 1380,
  caption: "Figure 10. Pooled correlation between sub-daily surface HCHO and the mean TEMPO column as a function of the lag of the TEMPO window from the sampling window, for the 3 h and 8 h sites. “Whole” uses the concentrations as measured; “anomalies” uses deviations from site and calendar-month means. Labels give the number of matched samples. Because the sites pooled here sample different windows, a given lag corresponds to different times of day at different sites (Sect. 4.10)." } },
{ fig: { file: "fig12_national_by_start_hour.png", w: 2400, h: 1380,
  caption: "Figure 11. The same correlations grouped by the local standard hour at which the sampling window begins, using only scans inside the sampling window. In the 3 h panel, the windows beginning at 05:00, 12:00 and 16:00 are the two California sites and the window beginning at 06:00 is the two Colorado sites; in the 8 h panel each point pools all 40 sites. Labels give the number of matched samples." } }
];
S.splice(byHead("5 Discussion"), 0, ...natResults);

// new Table 5, placed at the start of Sect. 4.9 (after its heading)
